{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "children",
      "type": "string",
      "description": "The markdown string to render.",
      "required": true
    },
    {
      "name": "display",
      "type": "'block' | 'inline'",
      "description": "Display type. Markdown defaults to block. Use 'inline' for markdown spans embedded inside text.",
      "default": "'block'"
    },
    {
      "name": "density",
      "type": "'default' | 'compact'",
      "description": "Controls spacing between block-level elements.",
      "default": "'default'"
    },
    {
      "name": "headingLevelStart",
      "type": "1 | 2 | 3 | 4 | 5 | 6",
      "description": "The HTML heading level that markdown # maps to. Shifts all heading levels down to fit the surrounding page hierarchy. Levels exceeding h6 are clamped to h6.",
      "default": "1"
    },
    {
      "name": "isStreaming",
      "type": "boolean",
      "description": "Enables streaming mode; it uses incremental parsing and a smooth fade-in animation for chunk-by-chunk text delivery.",
      "default": "false"
    },
    {
      "name": "onLinkClick",
      "type": "(href: string, event: MouseEvent) => void | false",
      "description": "Handler for link clicks. Return false to prevent the default navigation behavior. Link destinations in the markdown follow the shared navigation rule described on the Link `href` prop: a blocked destination renders as plain text and never reaches this handler or a custom link renderer. Image URLs use a separate, stricter policy (every data: URL is rejected)."
    },
    {
      "name": "sources",
      "type": "Record<string, MarkdownSource>",
      "description": "Citation sources keyed by ID. When provided, [id] and 【id】 markers in the markdown that match a key are rendered as citation chips."
    },
    {
      "name": "citationStyle",
      "type": "'label' | 'number'",
      "description": "How citations are displayed inline. 'label' shows a chip with source title, icon, and border. 'number' shows a compact numbered badge.",
      "default": "'label'"
    },
    {
      "name": "contentWidth",
      "type": "number | string",
      "description": "Max width for prose content (paragraphs, headings, lists, blockquotes). Tables and code blocks are unconstrained and can expand to the full container width. Use for readable line lengths in wide layouts.",
      "default": "680"
    },
    {
      "name": "contentAlign",
      "type": "'start' | 'center'",
      "description": "Alignment of prose content within the container when contentWidth is narrower than the available space.",
      "default": "'start'"
    },
    {
      "name": "plugins",
      "type": "readonly MarkdownPluginEntry[]",
      "description": "Ordered extensions created by createMarkdownPlugin(). Plugins may add bounded syntax, immutable typed AST transforms, and typed extension renderers. Use isMarkdownExtensionNode() to narrow extension data observed from other plugins. Renderer callbacks are pure; return a child component when hooks are needed. Omitted and empty lists preserve the released Markdown behavior."
    },
    {
      "name": "inlinePlugins",
      "type": "MarkdownInlinePlugin[]",
      "description": "Transforms regex matches in parsed text nodes into custom inline React elements. Use for prefixed identifiers, mentions, and other shorthand patterns. Inline code, fenced code blocks, and math are unaffected."
    },
    {
      "name": "autolink",
      "type": "'gfm'",
      "description": "Opt-in autolinking of bare URLs and emails. 'gfm' applies GitHub-Flavored Markdown autolink-literal rules: bare https?://..., www...., <scheme:url>, <email>, and user@host all become links. Trailing sentence punctuation and unbalanced trailing close-parens are excluded; matches inside code spans, code blocks, existing links, and image alt text are skipped. Default behavior (option unset) is unchanged."
    },
    {
      "name": "codeLanguages",
      "type": "ReadonlyArray<CodeLanguage>",
      "description": "CodeBlock language values a fence may name, each imported on its own (e.g. graphql from @astryxdesign/core/CodeBlock/languages/graphql) or made with createCodeLanguage. A fence whose language word is one of a listed value's identifiers renders with it, ahead of a built-in; a diff-<identifier> fence takes the diff layer over it; a later entry wins. Pass the same list to RichTextEditor or RichTextView so read and edit match."
    },
    {
      "name": "components",
      "type": "MarkdownComponents",
      "description": "Custom React component overrides for rendered Markdown elements (code, inlineCode, math, link, heading, paragraph, image, blockquote, hr, citation). Providing math enables `$…$` inline and `$$…$$` display parsing and receives `{value, display}`; omit it when dollar text should stay literal."
    },
    {
      "name": "xstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
    },
    {
      "name": "className",
      "type": "string",
      "description": "CSS class name for the root element. Prefer xstyle for styling; className is provided for integration with non-StyleX systems."
    },
    {
      "name": "style",
      "type": "CSSProperties",
      "description": "Inline styles for the root element. Prefer xstyle for styling; inline styles bypass StyleX optimization."
    },
    {
      "name": "data-testid",
      "type": "string",
      "description": "Test selector for automated testing frameworks."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
